1591       Pred != NanPred || X->getType() != Y->getType())
1592     std::swap(BO10, BO11);
1593 
1594   if (!match(BO10, m_FCmp(Pred, m_Value(Y), m_AnyZeroFP())) ||
1595       Pred != NanPred || X->getType() != Y->getType())
